R=itest-dup-01-q1; T4=stop; REPLAYED=stop; run_test $R 42 --scenario smoke --duration 60 && keep $P/$R.reconcile.json $P/$R.reconcile.pre-replay.json && keep $P/$R/events.jsonl $P/$R.events.pre-replay.jsonl && T4=ok || stop "test 4: the first run did not complete, or its pre-replay copies were not saved - do NOT replay (T4=$T4)"   # the copies keep the pre-replay accounting: the second fetch and the second check below overwrite both originals
replay() { python -m egw_simulator run --scenario smoke --seed 42 --duration 60 --run-id $R --output ~/egw-tcg/itest-replay --broker 127.0.0.1 --port $MQTT_PORT --username egw-simulator --password "$MOSQUITTO_SIMULATOR_PASSWORD" --ca-cert ~/egw-tcg/ca.crt --egw-id egw-01 --qos 1; }
if [ "$T4" = ok ] && wait_ready && drained; then T4=replayed; replay; RC=$?; echo "replay simulator exit=$RC (must be 0)"; [ "$RC" = 0 ] && REPLAYED=ok || stop "test 4: the replay simulator failed - do not evaluate; repeat the whole test under a new run id"; else stop "test 4: T4='$T4' is not 'ok' (the first line of this test did not complete, or the replay was already published once), or the controller is not ready and drained - the replay was NOT published"; fi
[ "$REPLAYED" = ok ] && drained && fetch $R && snap_pair $R replay && $REC same --prefix $P/$R after replay && REPLAYED=captured || stop "test 4: replay not published (REPLAYED='$REPLAYED'), replay state not captured, or twins DIFFERENT"    # 'drained' replaces the former 'sleep 65; repeat until queue_depth is 0': not a deadline, the replay can add no delivery
T4RC=stop; [ "$REPLAYED" = captured ] && { $REC replay-check $P/$R --replay-dir ~/egw-tcg/itest-replay/$R --events-before $P/$R.events.pre-replay.jsonl; T4RC=$?; }; case $T4RC in 0) true;; 5) stop "test 4: NOT DEMONSTRATED (replay check exit 5) - the replay's own duplicate line is not demonstrated for every replayed identity (the NOT DEMONSTRATED lines above name them, with their added duplicate lines and k, the reconnections between the 'after' and 'replay' readings): test 4 is NOT passed, and no condition failed";; *) stop "test 4: the per-identity replay check was not run (REPLAYED='$REPLAYED'), could not read its inputs (exit 1: test 4 NOT evaluated) or FAILED (exit 4) - test 4 passes only when it exits 0";; esac     # decision of 2026-09-30: the replayed identities are the message_ids of the replay's own sent_events.jsonl; the replay's lines are those the re-fetched events.jsonl holds beyond the pre-replay copy, each received after the 'after' reading (one received at or before it: exit 1); the /metrics readings 'after' and 'replay' must be of one process before anything is differenced; exit 5 (2026-10-01): with k reconnections between the two readings (the mqtt_connection delta), a replayed identity with 1 to k duplicate lines in the replay interval is not demonstrated, its lines may all be redeliveries of the first run - not a pass and not a failure, its own STOP; a failure (exit 4) takes precedence; it writes nothing; UNVERIFIED: on real event logs and /metrics readings (Appendix B, item 24)
[ "$REPLAYED" = captured ] && python3 -c "import json,sys;a=json.load(open('$P/$R.metrics.after.json'));b=json.load(open('$P/$R.metrics.replay.json'));one=a['started_at']==b['started_at'] and all(b[k]>=a[k] for k in ('uptime_s','received','accepted','rejected','duplicate','failed','dropped','processing_errors','mqtt_connection'));print({k:b[k]-a[k] for k in ('accepted','rejected','duplicate','failed','dropped')} if one else 'no difference taken:','same controller process:',one);sys.exit(0 if one else 1)" || stop "test 4: not evaluated (REPLAYED='$REPLAYED'), or the 'after' and 'replay' readings are not of one controller process (the same started_at; uptime_s, the cumulative counters and mqtt_connection non-decreasing) - no difference was taken"     # decision of 2026-09-30: no difference across two processes (CONTRACTS 5, rule 1); the replay check above fails test 4 on such readings
[ "$REPLAYED" = captured ] && $REC check $P/$R && keep $P/$R.reconcile.json $P/$R.reconcile.post-replay.json || stop "test 4: second check not run (REPLAYED='$REPLAYED') or non-zero, or the post-replay copy already exists"      # check again, on the re-fetched log: double_accepted = 0 and delivered_unique unchanged; its duplicates counts every duplicate line of the whole log and is reported (the per-identity judgement is replay-check's)
[ "$REPLAYED" = captured ] && python3 -c "import json;a=json.load(open('$P/$R.reconcile.pre-replay.json'));b=json.load(open('$P/$R.reconcile.post-replay.json'));[print(k,'pre-replay',a[k],'post-replay',b[k],'' if k=='duplicates' else ('UNCHANGED' if a[k]==b[k] else 'CHANGED')) for k in ('sent_valid','delivered_unique','lost','late_confirmations','double_accepted','duplicates')]" || stop "test 4: not evaluated (REPLAYED='$REPLAYED')"
[ "$REPLAYED" = captured ] && python3 -c "import json,collections; ev=[json.loads(l) for l in open('$HOME/egw-tcg/itest/$R/events.jsonl')]; print(collections.Counter(e['outcome'] for e in ev)); print('accepted unique:', len({e['message_id'] for e in ev if e['outcome']=='accepted'}), 'accepted total:', sum(e['outcome']=='accepted' for e in ev))" || stop "test 4: not evaluated (REPLAYED='$REPLAYED')"
